<?php $period=$variance['period'];$previous=$variance['previous'];$summary=$variance['summary']; ?>
<div class="page-header d-flex justify-content-between align-items-start flex-wrap gap-2"><div><h1>Payroll variance review</h1><p class="subtitle"><?= e($period['name']) ?> compared with <?= e($previous['name']??'no previous payroll') ?></p></div><a class="btn btn-soft btn-sm" href="/admin/payroll/<?= (int)$period['id'] ?>">Back to payroll</a></div>
<?php include config('app.paths.views').'/partials/alerts.php'; ?>
<div class="alert alert-info"><i data-lucide="info" class="me-2"></i>Employees with a net-pay change of 10% or more are highlighted. Review new hires, deductions, unpaid leave, overtime, and salary changes before approval.</div>
<div class="row g-3 mb-3"><div class="col-md-3"><div class="metric-card tone-purple"><div class="metric-label">Current net</div><div class="metric-value fs-5"><?= format_money($period['total_net']) ?></div></div></div><div class="col-md-3"><div class="metric-card tone-blue"><div class="metric-label">Net change</div><div class="metric-value fs-5 <?= $summary['net_change']<0?'text-danger':'' ?>"><?= ($summary['net_change']>=0?'+':'').format_money($summary['net_change']) ?></div></div></div><div class="col-md-3"><div class="metric-card tone-mint"><div class="metric-label">Headcount change</div><div class="metric-value"><?= $summary['headcount_change']>=0?'+':'' ?><?= (int)$summary['headcount_change'] ?></div></div></div><div class="col-md-3"><div class="metric-card tone-orange"><div class="metric-label">Exceptions</div><div class="metric-value"><?= (int)$summary['exceptions'] ?></div></div></div></div>
<div class="card ems-card mb-3"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Employee</th><th class="text-end">Previous net</th><th class="text-end">Current net</th><th class="text-end">Change</th><th>Review</th></tr></thead><tbody><?php if(!$variance['rows']): ?><tr><td colspan="5"><div class="empty-state py-5">Process payroll before reviewing variance.</div></td></tr><?php endif; ?><?php foreach($variance['rows'] as $row): ?><tr class="<?= $row['is_exception']?'table-warning':'' ?>"><td><strong><?= e($row['first_name'].' '.$row['last_name']) ?></strong><div class="small text-secondary"><?= e($row['employee_code']) ?></div></td><td class="text-end"><?= $row['previous_net']===null?'—':format_money($row['previous_net']) ?></td><td class="text-end fw-semibold"><?= format_money($row['net_salary']) ?></td><td class="text-end <?= $row['net_change']<0?'text-danger':'text-success' ?>"><?= $row['net_change']>=0?'+':'' ?><?= format_money($row['net_change']) ?><div class="small"><?= $row['net_change_percent']===null?'New':(($row['net_change_percent']>=0?'+':'').$row['net_change_percent'].'%') ?></div></td><td><?= $row['is_new']?'<span class="badge text-bg-info">New employee</span>':($row['is_exception']?'<span class="badge text-bg-warning">Variance</span>':'<span class="text-success small">Within range</span>') ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php if($period['status']==='calculated' && can('payroll.approve')): ?><div class="card ems-card"><div class="card-body"><form method="POST" action="/admin/payroll/<?= (int)$period['id'] ?>/approve" data-confirm="Approve payroll after recording this variance review?"><?= csrf_field() ?><input type="hidden" name="variance_confirmed" value="1"><label class="form-check mb-3"><input class="form-check-input" type="checkbox" required><span class="form-check-label">I reviewed the highlighted employee changes and payroll totals.</span></label><button class="btn btn-success"><i data-lucide="badge-check" class="me-1"></i>Approve payroll</button></form></div></div><?php endif; ?>
